<?php
namespace App\Controllers;

use App\Core\{Auth,Authorization,CSRF,Database,TenantContext,View,Audit,HttpException};
use App\Services\{AutoTenantService,AutoAvailabilityService,ModuleService,PackageService,LoyaltyService,BehaviorEngine,NotificationService};

final class AutoOperationsController
{
    public function dashboard():void
    {
        Authorization::require('auto.dashboard.view');$t=$this->tenant();$pdo=Database::connection();
        $stats=[];
        foreach([
            'today_jobs'=>"SELECT COUNT(*) FROM auto_jobs j JOIN appointments a ON a.id=j.appointment_id WHERE j.tenant_id=:t AND DATE(a.starts_at)=CURDATE() AND j.status<>'cancelled'",
            'in_service'=>"SELECT COUNT(*) FROM auto_jobs WHERE tenant_id=:t AND status IN('received','queue','preparation','in_service','drying','curing','ready')",
            'ready'=>"SELECT COUNT(*) FROM auto_jobs WHERE tenant_id=:t AND status='ready'",
            'active_bays'=>"SELECT COUNT(*) FROM auto_service_bays WHERE tenant_id=:t AND active=1",
        ] as $k=>$sql){$q=$pdo->prepare($sql);$q->execute(['t'=>$t]);$stats[$k]=(int)$q->fetchColumn();}
        $q=$pdo->prepare("SELECT COALESCE(SUM(total_amount),0) FROM auto_commands WHERE tenant_id=:t AND status='closed' AND DATE(closed_at)=CURDATE()");$q->execute(['t'=>$t]);$stats['revenue_today']=(float)$q->fetchColumn();
        $q=$pdo->prepare("SELECT j.id,j.status,a.starts_at,a.ends_at,c.name customer_name,s.name service_name,v.make,v.model,v.plate,b.name bay_name
          FROM auto_jobs j JOIN appointments a ON a.id=j.appointment_id JOIN customers c ON c.id=a.customer_id JOIN services s ON s.id=a.service_id JOIN customer_vehicles v ON v.id=j.vehicle_id LEFT JOIN auto_service_bays b ON b.id=j.bay_id
          WHERE j.tenant_id=:t AND j.status NOT IN('cancelled','delivered') ORDER BY a.starts_at LIMIT 30");$q->execute(['t'=>$t]);
        View::render('auto/dashboard',['title'=>'Gestão Automotiva','stats'=>$stats,'jobs'=>$q->fetchAll()]);
    }

    public function bays():void
    {
        Authorization::require('auto.bays.view');$t=$this->tenant();$pdo=Database::connection();
        $q=$pdo->prepare("SELECT b.*, (SELECT COUNT(*) FROM auto_jobs j WHERE j.tenant_id=b.tenant_id AND j.bay_id=b.id AND j.status IN('received','queue','preparation','in_service','drying','curing')) current_jobs FROM auto_service_bays b WHERE b.tenant_id=:t ORDER BY b.active DESC,b.sort_order,b.name");$q->execute(['t'=>$t]);$bays=$q->fetchAll();
        $h=$pdo->prepare('SELECT * FROM auto_bay_hours WHERE tenant_id=:t ORDER BY bay_id,weekday,start_time');$h->execute(['t'=>$t]);$hours=[];foreach($h->fetchAll() as $row)$hours[(int)$row['bay_id']][]=$row;
        $s=$pdo->prepare('SELECT id,name FROM services WHERE tenant_id=:t AND active=1 ORDER BY name');$s->execute(['t'=>$t]);$services=$s->fetchAll();
        $m=$pdo->prepare('SELECT bay_id,service_id FROM auto_bay_services WHERE tenant_id=:t');$m->execute(['t'=>$t]);$mapped=[];foreach($m->fetchAll() as $row)$mapped[(int)$row['bay_id']][]=(int)$row['service_id'];
        View::render('auto/bays',['title'=>'Boxes / Vagas','bays'=>$bays,'hours'=>$hours,'services'=>$services,'mapped'=>$mapped]);
    }

    public function saveBay():void
    {
        Authorization::require('auto.bays.manage');CSRF::enforce();$t=$this->tenant();$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$type=(string)($_POST['bay_type']??'box');$buffer=max(0,min(240,(int)($_POST['buffer_minutes']??0)));$notes=trim((string)($_POST['notes']??''))?:null;$active=isset($_POST['active'])?1:0;
        if(mb_strlen($name)<2||!in_array($type,['box','vaga','elevador','lavagem','detailing','secagem','outro'],true))HttpException::abort(422,'Dados do box inválidos.');$pdo=Database::connection();
        if($id){$q=$pdo->prepare('UPDATE auto_service_bays SET name=:n,bay_type=:type,buffer_minutes=:b,notes=:notes,active=:a,updated_at=NOW() WHERE id=:id AND tenant_id=:t');$q->execute(['n'=>$name,'type'=>$type,'b'=>$buffer,'notes'=>$notes,'a'=>$active,'id'=>$id,'t'=>$t]);if(!$q->rowCount()){$x=$pdo->prepare('SELECT 1 FROM auto_service_bays WHERE id=:id AND tenant_id=:t');$x->execute(['id'=>$id,'t'=>$t]);if(!$x->fetchColumn())HttpException::abort(404,'Box não encontrado.');}}
        else{$pdo->prepare('INSERT INTO auto_service_bays(tenant_id,name,bay_type,buffer_minutes,notes,active,created_at,updated_at)VALUES(:t,:n,:type,:b,:notes,:a,NOW(),NOW())')->execute(['t'=>$t,'n'=>$name,'type'=>$type,'b'=>$buffer,'notes'=>$notes,'a'=>$active]);$id=(int)$pdo->lastInsertId();}
        $pdo->prepare('DELETE FROM auto_bay_services WHERE tenant_id=:t AND bay_id=:b')->execute(['t'=>$t,'b'=>$id]);foreach(array_unique(array_map('intval',(array)($_POST['service_ids']??[]))) as $sid){if($sid<=0)continue;$v=$pdo->prepare('SELECT 1 FROM services WHERE id=:s AND tenant_id=:t AND active=1');$v->execute(['s'=>$sid,'t'=>$t]);if($v->fetchColumn())$pdo->prepare('INSERT IGNORE INTO auto_bay_services(bay_id,service_id,tenant_id)VALUES(:b,:s,:t)')->execute(['b'=>$id,'s'=>$sid,'t'=>$t]);}
        Audit::log('auto.bay.saved','auto_service_bays',$id);header('Location: /auto/bays');exit;
    }

    public function saveBayHours(string $id):void
    {
        Authorization::require('auto.bays.manage');CSRF::enforce();$t=$this->tenant();$bay=(int)$id;$pdo=Database::connection();$q=$pdo->prepare('SELECT 1 FROM auto_service_bays WHERE id=:b AND tenant_id=:t');$q->execute(['b'=>$bay,'t'=>$t]);if(!$q->fetchColumn())HttpException::abort(404,'Box não encontrado.');
        $pdo->beginTransaction();try{$pdo->prepare('DELETE FROM auto_bay_hours WHERE tenant_id=:t AND bay_id=:b')->execute(['t'=>$t,'b'=>$bay]);for($d=1;$d<=7;$d++){$start=trim((string)($_POST['start_'.$d]??''));$end=trim((string)($_POST['end_'.$d]??''));if($start===''||$end==='')continue;if(!preg_match('/^\d{2}:\d{2}$/',$start)||!preg_match('/^\d{2}:\d{2}$/',$end)||$end<=$start)throw new \DomainException('Horário inválido no dia '.$d.'.');$pdo->prepare('INSERT INTO auto_bay_hours(tenant_id,bay_id,weekday,start_time,end_time,active)VALUES(:t,:b,:d,:s,:e,1)')->execute(['t'=>$t,'b'=>$bay,'d'=>$d,'s'=>$start.':00','e'=>$end.':00']);}$pdo->commit();}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();HttpException::abort(422,$e->getMessage());}
        header('Location: /auto/bays');exit;
    }

    public function createBooking():void
    {
        Authorization::require('auto.jobs.manage');$t=$this->tenant();$pdo=Database::connection();$q=$pdo->prepare("SELECT id,name FROM customers WHERE tenant_id=:t AND status='active' ORDER BY name");$q->execute(['t'=>$t]);$customers=$q->fetchAll();$q=$pdo->prepare('SELECT id,name,duration_minutes,price FROM services WHERE tenant_id=:t AND active=1 ORDER BY name');$q->execute(['t'=>$t]);$services=$q->fetchAll();$q=$pdo->prepare("SELECT v.id,v.customer_id,CONCAT(COALESCE(v.make,''),' ',v.model,IF(v.plate IS NULL OR v.plate='','',CONCAT(' • ',v.plate))) label FROM customer_vehicles v WHERE v.tenant_id=:t AND v.active=1 ORDER BY v.model");$q->execute(['t'=>$t]);$vehicles=$q->fetchAll();$q=$pdo->prepare('SELECT id,name FROM professionals WHERE tenant_id=:t AND active=1 ORDER BY name');$q->execute(['t'=>$t]);View::render('auto/create-booking',['title'=>'Novo atendimento automotivo','customers'=>$customers,'services'=>$services,'vehicles'=>$vehicles,'professionals'=>$q->fetchAll()]);
    }

    public function bookingAvailability():void
    {
        Authorization::require('auto.jobs.manage');header('Content-Type: application/json; charset=utf-8');$t=$this->tenant();$service=(int)($_GET['service_id']??0);$date=(string)($_GET['date']??'');if(!$service||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){http_response_code(422);echo json_encode(['slots'=>[]]);return;}try{$day=new \DateTimeImmutable($date.' 00:00:00');}catch(\Throwable){http_response_code(422);echo json_encode(['slots'=>[]]);return;}echo json_encode(['slots'=>(new AutoAvailabilityService())->slots($t,$service,$day)],JSON_UNESCAPED_UNICODE);
    }

    public function storeBooking():void
    {
        Authorization::require('auto.jobs.manage');CSRF::enforce();$t=$this->tenant();$customer=(int)($_POST['customer_id']??0);$vehicle=(int)($_POST['vehicle_id']??0);$service=(int)($_POST['service_id']??0);$bay=(int)($_POST['bay_id']??0);$professional=(int)($_POST['professional_id']??0)?:null;try{$start=new \DateTimeImmutable((string)($_POST['starts_at']??''));}catch(\Throwable){HttpException::abort(422,'Escolha um horário válido.');}$engine=new AutoAvailabilityService();$sv=$engine->service($t,$service);if(!$customer||!$vehicle||!$bay||!$sv)HttpException::abort(422,'Cliente, veículo, serviço e box são obrigatórios.');$pdo=Database::connection();$q=$pdo->prepare("SELECT 1 FROM customer_vehicles v JOIN customers c ON c.id=v.customer_id WHERE v.id=:v AND v.customer_id=:c AND v.tenant_id=:t AND v.active=1 AND c.status='active'");$q->execute(['v'=>$vehicle,'c'=>$customer,'t'=>$t]);if(!$q->fetchColumn())HttpException::abort(422,'Veículo não pertence ao cliente.');if(!$this->validBay($pdo,$t,$bay,$service))HttpException::abort(422,'Box inválido para o serviço.');if($professional){$q=$pdo->prepare('SELECT 1 FROM professionals WHERE id=:p AND tenant_id=:t AND active=1');$q->execute(['p'=>$professional,'t'=>$t]);if(!$q->fetchColumn())HttpException::abort(422,'Profissional inválido.');}$end=$start->modify('+'.(int)$sv['duration_minutes'].' minutes');$settings=$engine->settings($t);$bq=$pdo->prepare('SELECT buffer_minutes FROM auto_service_bays WHERE id=:b AND tenant_id=:t');$bq->execute(['b'=>$bay,'t'=>$t]);$buffer=max((int)($settings['default_buffer_minutes']??0),(int)$bq->fetchColumn());$offered=false;foreach($engine->slots($t,$service,new \DateTimeImmutable($start->format('Y-m-d').' 00:00:00'),$bay) as $slot){if($slot['starts_at']===$start->format('Y-m-d H:i:s')){$offered=true;break;}}if(!$offered||!$engine->bayAvailable($t,$bay,$start,$end,$buffer,null))HttpException::abort(409,'O box não está disponível neste horário.');$lock="auto-book:$t:$bay";$lk=$pdo->prepare('SELECT GET_LOCK(:n,5)');$lk->execute(['n'=>$lock]);if((int)$lk->fetchColumn()!==1)HttpException::abort(409,'Agenda ocupada.');$token=bin2hex(random_bytes(24));try{$pdo->beginTransaction();if(!$engine->bayAvailable($t,$bay,$start,$end,$buffer,null))throw new \LogicException('Horário já ocupado.');$pdo->prepare("INSERT INTO appointments(tenant_id,customer_id,vehicle_id,professional_id,service_id,service_price_snapshot,starts_at,ends_at,status,source,notes,customer_manage_token_hash,customer_manage_token_encrypted,created_by,created_at,updated_at)VALUES(:t,:c,:v,:p,:s,:price,:st,:en,'confirmed','internal',:notes,:h,:enc,:u,NOW(),NOW())")->execute(['t'=>$t,'c'=>$customer,'v'=>$vehicle,'p'=>$professional,'s'=>$service,'price'=>$sv['price'],'st'=>$start->format('Y-m-d H:i:s'),'en'=>$end->format('Y-m-d H:i:s'),'notes'=>trim((string)($_POST['notes']??''))?:null,'h'=>hash('sha256',$token),'enc'=>\App\Core\Encryption::encrypt(['token'=>$token]),'u'=>Auth::user()['id']]);$appointment=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO auto_jobs(tenant_id,appointment_id,vehicle_id,bay_id,assigned_professional_id,status,expected_ready_at,created_at,updated_at)VALUES(:t,:a,:v,:b,:p,'scheduled',:e,NOW(),NOW())")->execute(['t'=>$t,'a'=>$appointment,'v'=>$vehicle,'b'=>$bay,'p'=>$professional,'e'=>$end->format('Y-m-d H:i:s')]);$job=(int)$pdo->lastInsertId();$this->seedSteps($pdo,$t,$job,$service);$this->history($pdo,$t,$job,null,'scheduled','Agendamento interno');$pdo->commit();}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();HttpException::abort($e instanceof \LogicException?409:422,$e->getMessage());}finally{$pdo->prepare('SELECT RELEASE_LOCK(:n)')->execute(['n'=>$lock]);}Audit::log('auto.booking.created','auto_jobs',$job);header('Location: /auto/jobs/'.$job);exit;
    }

    public function jobs():void
    {
        Authorization::require('auto.jobs.view');$t=$this->tenant();$pdo=Database::connection();$status=trim((string)($_GET['status']??''));$where=$status!==''?' AND j.status=:status':'';
        $q=$pdo->prepare("SELECT j.*,a.starts_at,a.ends_at,a.status appointment_status,c.name customer_name,c.phone customer_phone,s.name service_name,v.make,v.model,v.plate,b.name bay_name,p.name professional_name,ac.id command_id,ac.status command_status
          FROM auto_jobs j JOIN appointments a ON a.id=j.appointment_id JOIN customers c ON c.id=a.customer_id JOIN services s ON s.id=a.service_id JOIN customer_vehicles v ON v.id=j.vehicle_id LEFT JOIN auto_service_bays b ON b.id=j.bay_id LEFT JOIN professionals p ON p.id=j.assigned_professional_id LEFT JOIN auto_commands ac ON ac.job_id=j.id AND ac.tenant_id=j.tenant_id
          WHERE j.tenant_id=:t{$where} ORDER BY (j.status='ready') DESC,a.starts_at DESC LIMIT 400");$params=['t'=>$t];if($status!=='')$params['status']=$status;$q->execute($params);
        $pending=$pdo->prepare("SELECT a.id,a.starts_at,c.name customer_name,s.name service_name,v.model,v.plate FROM appointments a JOIN customers c ON c.id=a.customer_id JOIN services s ON s.id=a.service_id JOIN customer_vehicles v ON v.id=a.vehicle_id LEFT JOIN auto_jobs j ON j.tenant_id=a.tenant_id AND j.appointment_id=a.id WHERE a.tenant_id=:t AND a.vehicle_id IS NOT NULL AND j.id IS NULL AND a.status NOT IN('cancelled','no_show','completed') ORDER BY a.starts_at LIMIT 100");$pending->execute(['t'=>$t]);
        View::render('auto/jobs',['title'=>'Ordens / Serviços','jobs'=>$q->fetchAll(),'pendingAppointments'=>$pending->fetchAll(),'filterStatus'=>$status]);
    }

    public function createJob():void
    {
        Authorization::require('auto.jobs.manage');CSRF::enforce();$t=$this->tenant();$appointment=(int)($_POST['appointment_id']??0);$bay=(int)($_POST['bay_id']??0)?:null;$pdo=Database::connection();$q=$pdo->prepare('SELECT a.*,s.duration_minutes FROM appointments a JOIN services s ON s.id=a.service_id WHERE a.id=:a AND a.tenant_id=:t AND a.vehicle_id IS NOT NULL');$q->execute(['a'=>$appointment,'t'=>$t]);$a=$q->fetch();if(!$a)HttpException::abort(422,'Agendamento automotivo inválido.');
        if($bay&&!$this->validBay($pdo,$t,$bay,(int)$a['service_id']))HttpException::abort(422,'Box inválido para este serviço.');
        $pdo->prepare("INSERT INTO auto_jobs(tenant_id,appointment_id,vehicle_id,bay_id,assigned_professional_id,status,expected_ready_at,created_at,updated_at) VALUES(:t,:a,:v,:b,:p,'scheduled',:ready,NOW(),NOW()) ON DUPLICATE KEY UPDATE bay_id=COALESCE(VALUES(bay_id),bay_id),updated_at=NOW()")
            ->execute(['t'=>$t,'a'=>$appointment,'v'=>$a['vehicle_id'],'b'=>$bay,'p'=>$a['professional_id'],'ready'=>$a['ends_at']]);
        $id=(int)$pdo->lastInsertId();if(!$id){$x=$pdo->prepare('SELECT id FROM auto_jobs WHERE tenant_id=:t AND appointment_id=:a');$x->execute(['t'=>$t,'a'=>$appointment]);$id=(int)$x->fetchColumn();}
        $this->seedSteps($pdo,$t,$id,(int)$a['service_id']);Audit::log('auto.job.created','auto_jobs',$id);header('Location: /auto/jobs/'.$id);exit;
    }

    public function job(string $id):void
    {
        Authorization::require('auto.jobs.view');$t=$this->tenant();$job=$this->jobRow($t,(int)$id);$pdo=Database::connection();
        $q=$pdo->prepare('SELECT * FROM auto_job_inspection_items WHERE tenant_id=:t AND job_id=:j ORDER BY phase,id');$q->execute(['t'=>$t,'j'=>$job['id']]);$inspection=$q->fetchAll();
        $q=$pdo->prepare('SELECT * FROM auto_job_photos WHERE tenant_id=:t AND job_id=:j ORDER BY created_at DESC');$q->execute(['t'=>$t,'j'=>$job['id']]);$photos=$q->fetchAll();
        $q=$pdo->prepare('SELECT * FROM auto_job_steps WHERE tenant_id=:t AND job_id=:j ORDER BY sort_order,id');$q->execute(['t'=>$t,'j'=>$job['id']]);$steps=$q->fetchAll();
        $q=$pdo->prepare('SELECT e.*,COALESCE((SELECT COUNT(*) FROM auto_estimate_items i WHERE i.estimate_id=e.id),0) item_count FROM auto_estimates e WHERE e.tenant_id=:t AND e.job_id=:j ORDER BY e.id DESC');$q->execute(['t'=>$t,'j'=>$job['id']]);$estimates=$q->fetchAll();foreach($estimates as &$est){try{$est['_token']=(string)(\App\Core\Encryption::decrypt($est['public_token_encrypted'])['token']??'');}catch(\Throwable){$est['_token']='';}}unset($est);$dq=$pdo->prepare('SELECT * FROM auto_delivery_terms WHERE tenant_id=:t AND job_id=:j');$dq->execute(['t'=>$t,'j'=>$job['id']]);$delivery=$dq->fetch()?:null;if($delivery){try{$delivery['_token']=(string)(\App\Core\Encryption::decrypt($delivery['public_token_encrypted'])['token']??'');}catch(\Throwable){$delivery['_token']='';}}
        $q=$pdo->prepare('SELECT id,name FROM auto_service_bays WHERE tenant_id=:t AND active=1 ORDER BY sort_order,name');$q->execute(['t'=>$t]);$bays=$q->fetchAll();
        $q=$pdo->prepare('SELECT id,name FROM professionals WHERE tenant_id=:t AND active=1 ORDER BY name');$q->execute(['t'=>$t]);$professionals=$q->fetchAll();
        $q=$pdo->prepare('SELECT id,name,price FROM services WHERE tenant_id=:t AND active=1 ORDER BY name');$q->execute(['t'=>$t]);$services=$q->fetchAll();
        $q=$pdo->prepare('SELECT id,name,sale_price FROM products WHERE tenant_id=:t AND active=1 ORDER BY name');$q->execute(['t'=>$t]);$products=$q->fetchAll();
        $q=$pdo->prepare('SELECT u.*,p.name product_name,p.unit FROM auto_job_material_usage u JOIN products p ON p.id=u.product_id WHERE u.tenant_id=:t AND u.job_id=:j ORDER BY u.id DESC');$q->execute(['t'=>$t,'j'=>$job['id']]);$materialsUsed=$q->fetchAll();
        $q=$pdo->prepare('SELECT * FROM auto_job_technical_details WHERE tenant_id=:t AND job_id=:j');$q->execute(['t'=>$t,'j'=>$job['id']]);$technical=$q->fetch()?:[];
        View::render('auto/job',['title'=>'Ordem #'.$job['id'],'job'=>$job,'inspection'=>$inspection,'photos'=>$photos,'steps'=>$steps,'estimates'=>$estimates,'delivery'=>$delivery,'bays'=>$bays,'professionals'=>$professionals,'services'=>$services,'products'=>$products,'materialsUsed'=>$materialsUsed,'technical'=>$technical]);
    }

    public function assign(string $id):void
    {
        Authorization::require('auto.jobs.manage');CSRF::enforce();$t=$this->tenant();$job=$this->jobRow($t,(int)$id);$pdo=Database::connection();$bay=(int)($_POST['bay_id']??0)?:null;$prof=(int)($_POST['professional_id']??0)?:null;
        if($bay&&!$this->validBay($pdo,$t,$bay,(int)$job['service_id']))HttpException::abort(422,'Box não atende este serviço.');if($prof){$q=$pdo->prepare('SELECT 1 FROM professionals WHERE id=:p AND tenant_id=:t AND active=1');$q->execute(['p'=>$prof,'t'=>$t]);if(!$q->fetchColumn())HttpException::abort(422,'Profissional inválido.');}
        if($bay){$avail=new AutoAvailabilityService();$settings=$avail->settings($t);$bq=$pdo->prepare('SELECT buffer_minutes FROM auto_service_bays WHERE id=:b AND tenant_id=:t');$bq->execute(['b'=>$bay,'t'=>$t]);$buffer=max((int)($settings['default_buffer_minutes']??0),(int)$bq->fetchColumn());if(!$avail->bayAvailable($t,$bay,new \DateTimeImmutable($job['starts_at']),new \DateTimeImmutable($job['ends_at']),$buffer,(int)$job['id']))HttpException::abort(409,'O box está ocupado neste horário.');}
        $pdo->prepare('UPDATE auto_jobs SET bay_id=:b,assigned_professional_id=:p,updated_at=NOW() WHERE id=:id AND tenant_id=:t')->execute(['b'=>$bay,'p'=>$prof,'id'=>$job['id'],'t'=>$t]);Audit::log('auto.job.assigned','auto_jobs',(int)$job['id']);header('Location: /auto/jobs/'.$job['id']);exit;
    }

    public function checkin(string $id):void
    {
        Authorization::require('auto.jobs.manage');CSRF::enforce();$t=$this->tenant();$job=$this->jobRow($t,(int)$id);$odo=max(0,(int)($_POST['odometer_in']??0))?:null;$fuel=(string)($_POST['fuel_level']??'unknown');if(!in_array($fuel,['empty','quarter','half','three_quarters','full','unknown'],true))$fuel='unknown';$keys=max(0,min(10,(int)($_POST['keys_received']??0)));$pdo=Database::connection();
        $pdo->prepare("UPDATE auto_jobs SET status='received',odometer_in=:o,fuel_level=:f,keys_received=:k,received_at=COALESCE(received_at,NOW()),updated_at=NOW() WHERE id=:id AND tenant_id=:t")->execute(['o'=>$odo,'f'=>$fuel,'k'=>$keys,'id'=>$job['id'],'t'=>$t]);
        if($odo)$pdo->prepare("INSERT INTO auto_vehicle_profiles(vehicle_id,tenant_id,current_odometer,updated_at)VALUES(:v,:t,:o,NOW()) ON DUPLICATE KEY UPDATE current_odometer=VALUES(current_odometer),updated_at=NOW()")->execute(['v'=>$job['vehicle_id'],'t'=>$t,'o'=>$odo]);
        $this->history($pdo,$t,(int)$job['id'],$job['status'],'received','Check-in realizado');$pdo->prepare("UPDATE appointments SET status='waiting',checked_in_at=COALESCE(checked_in_at,NOW()),updated_at=NOW() WHERE id=:a AND tenant_id=:t")->execute(['a'=>$job['appointment_id'],'t'=>$t]);Audit::log('auto.job.checkin','auto_jobs',(int)$job['id']);header('Location: /auto/jobs/'.$job['id']);exit;
    }

    public function status(string $id):void
    {
        Authorization::require('auto.jobs.manage');CSRF::enforce();$t=$this->tenant();$job=$this->jobRow($t,(int)$id);$status=(string)($_POST['status']??'');$allowed=['scheduled','received','queue','preparation','in_service','drying','curing','ready','delivered','cancelled'];if(!in_array($status,$allowed,true))HttpException::abort(422,'Status inválido.');$pdo=Database::connection();$extra='';$params=['s'=>$status,'id'=>$job['id'],'t'=>$t];
        if($status==='in_service')$extra=',started_at=COALESCE(started_at,NOW())';elseif($status==='ready')$extra=',ready_at=COALESCE(ready_at,NOW())';elseif($status==='delivered')$extra=',delivered_at=COALESCE(delivered_at,NOW())';
        if(in_array($status,['preparation','in_service'],true)){ $rq=$pdo->prepare('SELECT require_checkin_photos FROM auto_settings WHERE tenant_id=:t');$rq->execute(['t'=>$t]);if((int)$rq->fetchColumn()===1){$pq=$pdo->prepare("SELECT COUNT(*) FROM auto_job_photos WHERE tenant_id=:t AND job_id=:j AND phase IN('before','damage')");$pq->execute(['t'=>$t,'j'=>$job['id']]);if((int)$pq->fetchColumn()<1)HttpException::abort(409,'Registre ao menos uma foto de entrada antes de iniciar o serviço.');}}
        if($status==='delivered'){ $q=$pdo->prepare('SELECT id,status FROM auto_commands WHERE tenant_id=:t AND job_id=:j');$q->execute(['t'=>$t,'j'=>$job['id']]);$cmd=$q->fetch();if(!$cmd||$cmd['status']!=='closed')HttpException::abort(409,'Feche a comanda antes da entrega.');$rq=$pdo->prepare('SELECT require_delivery_acceptance FROM auto_settings WHERE tenant_id=:t');$rq->execute(['t'=>$t]);if((int)$rq->fetchColumn()===1){$dq=$pdo->prepare('SELECT accepted_at FROM auto_delivery_terms WHERE tenant_id=:t AND job_id=:j');$dq->execute(['t'=>$t,'j'=>$job['id']]);if(!$dq->fetchColumn())HttpException::abort(409,'O termo de entrega ainda não foi aceito pelo cliente.');} }
