    public function closeCommand(string $id):void
    {
        Authorization::require('auto.commands.manage');CSRF::enforce();$t=$this->tenant();$pdo=Database::connection();$cmd=$this->commandRow($pdo,$t,(int)$id,true);$paid=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM auto_command_payments WHERE command_id=:c AND tenant_id=:t');$paid->execute(['c'=>$cmd['id'],'t'=>$t]);if(round((float)$paid->fetchColumn(),2)+0.009<round((float)$cmd['total_amount'],2))HttpException::abort(409,'A comanda ainda possui saldo em aberto.');$pdo->beginTransaction();try{$items=$pdo->prepare('SELECT * FROM auto_command_items WHERE command_id=:c AND tenant_id=:t');$items->execute(['c'=>$cmd['id'],'t'=>$t]);$items=$items->fetchAll();$needs=[];foreach($items as $i){if($i['product_id'])$needs[(int)$i['product_id']]=($needs[(int)$i['product_id']]??0)+(float)$i['quantity'];}
            $actual=$pdo->prepare('SELECT product_id,SUM(quantity) quantity FROM auto_job_material_usage WHERE tenant_id=:t AND job_id=:j GROUP BY product_id');$actual->execute(['t'=>$t,'j'=>$cmd['job_id']]);$actualRows=$actual->fetchAll();if($actualRows){foreach($actualRows as $mat)$needs[(int)$mat['product_id']]=($needs[(int)$mat['product_id']]??0)+(float)$mat['quantity'];}else{foreach($items as $i){if(!$i['service_id'])continue;$m=$pdo->prepare('SELECT product_id,quantity FROM auto_service_materials WHERE tenant_id=:t AND service_id=:s');$m->execute(['t'=>$t,'s'=>$i['service_id']]);foreach($m->fetchAll() as $mat)$needs[(int)$mat['product_id']]=($needs[(int)$mat['product_id']]??0)+(float)$mat['quantity']*(float)$i['quantity'];}}
            if(ModuleService::has('stock',$t)){foreach($needs as $pid=>$qty){$p=$pdo->prepare('SELECT name,stock FROM products WHERE id=:p AND tenant_id=:t FOR UPDATE');$p->execute(['p'=>$pid,'t'=>$t]);$pr=$p->fetch();if(!$pr)throw new \DomainException('Produto/material não encontrado.');$balance=(float)$pr['stock']-$qty;if($balance<0)throw new \DomainException('Estoque insuficiente para '.$pr['name'].'.');$pdo->prepare('UPDATE products SET stock=:b,updated_at=NOW() WHERE id=:p AND tenant_id=:t')->execute(['b'=>$balance,'p'=>$pid,'t'=>$t]);$pdo->prepare("INSERT INTO product_stock_movements(tenant_id,product_id,type,quantity,balance_after,user_id,reason,created_at)VALUES(:t,:p,'command',:q,:b,:u,:r,NOW())")->execute(['t'=>$t,'p'=>$pid,'q'=>-$qty,'b'=>$balance,'u'=>Auth::user()['id'],'r'=>'Auto comanda #'.$cmd['id']]);}}
            $pdo->prepare("UPDATE auto_commands SET status='closed',closed_by=:u,closed_at=NOW(),updated_at=NOW() WHERE id=:c AND tenant_id=:t")->execute(['u'=>Auth::user()['id'],'c'=>$cmd['id'],'t'=>$t]);$pdo->prepare("UPDATE auto_jobs SET status='ready',ready_at=COALESCE(ready_at,NOW()),updated_at=NOW() WHERE id=:j AND tenant_id=:t")->execute(['j'=>$cmd['job_id'],'t'=>$t]);$pdo->prepare("UPDATE appointments SET status='completed',service_completed_at=COALESCE(service_completed_at,NOW()),updated_at=NOW() WHERE id=:a AND tenant_id=:t")->execute(['a'=>$cmd['appointment_id'],'t'=>$t]);
            if(ModuleService::has('finance',$t))$pdo->prepare("INSERT IGNORE INTO financial_transactions(tenant_id,appointment_id,source_type,source_id,type,description,amount,payment_method,status,idempotency_key,competence_at,paid_at,created_at,updated_at)VALUES(:t,:a,'auto_command',:sid,'income',:d,:amount,'outro','paid',:key,CURDATE(),NOW(),NOW(),NOW())")->execute(['t'=>$t,'a'=>$cmd['appointment_id'],'sid'=>$cmd['id'],'d'=>'Comanda automotiva #'.$cmd['id'],'amount'=>$cmd['total_amount'],'key'=>'auto-command-'.$cmd['id']]);
            $pdo->commit();}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();HttpException::abort(422,$e->getMessage());}
        PackageService::consumeForAppointment($t,(int)$cmd['appointment_id'],(int)$cmd['customer_id'],(int)$cmd['service_id']);LoyaltyService::earn($t,(int)$cmd['customer_id'],(float)$cmd['total_amount'],'appointment',(int)$cmd['appointment_id']);(new BehaviorEngine())->recalculateCustomer($t,(int)$cmd['customer_id']);$this->createAutoCommissions($t,(int)$cmd['id']);$this->scheduleReturn($t,(int)$cmd['job_id']);$this->ensureDeliveryTerm($t,(int)$cmd['job_id']);NotificationService::tenantOwners($t,'auto.ready','Veículo pronto',$cmd['vehicle_label'].' está pronto.','/auto/jobs/'.$cmd['job_id'],'success');header('Location: /auto/commands/'.$cmd['id']);exit;
    }

    public function crm():void
    {
        Authorization::require('auto.crm.view');$t=$this->tenant();$pdo=Database::connection();$q=$pdo->prepare("SELECT e.*,v.make,v.model,v.plate,c.name customer_name,c.phone,c.email FROM auto_crm_events e JOIN customer_vehicles v ON v.id=e.vehicle_id JOIN customers c ON c.id=e.customer_id WHERE e.tenant_id=:t ORDER BY (e.status='pending') DESC,e.due_at LIMIT 400");$q->execute(['t'=>$t]);$events=$q->fetchAll();$due=$pdo->prepare("SELECT v.id vehicle_id,v.make,v.model,v.plate,c.name customer_name,c.id customer_id,p.next_recommended_at,p.warranty_until FROM customer_vehicles v JOIN customers c ON c.id=v.customer_id LEFT JOIN auto_vehicle_profiles p ON p.vehicle_id=v.id WHERE v.tenant_id=:t AND v.active=1 ORDER BY COALESCE(p.next_recommended_at,'9999-12-31') LIMIT 400");$due->execute(['t'=>$t]);View::render('auto/crm',['title'=>'CRM Automotivo','events'=>$events,'vehicles'=>$due->fetchAll()]);
    }

    public function crmDone(string $id):void{Authorization::require('auto.crm.manage');CSRF::enforce();$t=$this->tenant();Database::connection()->prepare("UPDATE auto_crm_events SET status='done',updated_at=NOW() WHERE id=:id AND tenant_id=:t")->execute(['id'=>(int)$id,'t'=>$t]);header('Location: /auto/crm');exit;}

    public function reports():void
    {
        Authorization::require('auto.reports.view');$t=$this->tenant();$pdo=Database::connection();$from=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['from']??''))?$_GET['from']:date('Y-m-01');$to=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['to']??''))?$_GET['to']:date('Y-m-d');
        $q=$pdo->prepare("SELECT COUNT(*) jobs,COALESCE(SUM(CASE WHEN ac.status='closed' THEN ac.total_amount ELSE 0 END),0) revenue,COALESCE(AVG(CASE WHEN ac.status='closed' THEN ac.total_amount END),0) avg_ticket,COALESCE(AVG(CASE WHEN j.started_at IS NOT NULL AND j.ready_at IS NOT NULL THEN TIMESTAMPDIFF(MINUTE,j.started_at,j.ready_at) END),0) avg_execution_minutes FROM auto_jobs j JOIN appointments a ON a.id=j.appointment_id LEFT JOIN auto_commands ac ON ac.job_id=j.id AND ac.tenant_id=j.tenant_id WHERE j.tenant_id=:t AND DATE(a.starts_at) BETWEEN :f AND :to");$q->execute(['t'=>$t,'f'=>$from,'to'=>$to]);$summary=$q->fetch();
        $q=$pdo->prepare("SELECT s.name,COUNT(*) qty,COALESCE(SUM(ac.total_amount),0) revenue FROM auto_jobs j JOIN appointments a ON a.id=j.appointment_id JOIN services s ON s.id=a.service_id LEFT JOIN auto_commands ac ON ac.job_id=j.id AND ac.status='closed' WHERE j.tenant_id=:t AND DATE(a.starts_at) BETWEEN :f AND :to GROUP BY s.id,s.name ORDER BY qty DESC LIMIT 30");$q->execute(['t'=>$t,'f'=>$from,'to'=>$to]);$services=$q->fetchAll();
        $q=$pdo->prepare("SELECT b.name,COUNT(j.id) jobs FROM auto_service_bays b LEFT JOIN auto_jobs j ON j.bay_id=b.id AND j.tenant_id=b.tenant_id LEFT JOIN appointments a ON a.id=j.appointment_id AND DATE(a.starts_at) BETWEEN :f AND :to WHERE b.tenant_id=:t GROUP BY b.id,b.name ORDER BY jobs DESC");$q->execute(['t'=>$t,'f'=>$from,'to'=>$to]);View::render('auto/reports',['title'=>'Relatórios Automotivos','summary'=>$summary,'services'=>$services,'bays'=>$q->fetchAll(),'from'=>$from,'to'=>$to]);
    }

    public function settings():void
    {
        Authorization::require('auto.settings.manage');$t=$this->tenant();$pdo=Database::connection();$q=$pdo->prepare('SELECT * FROM auto_settings WHERE tenant_id=:t');$q->execute(['t'=>$t]);$settings=$q->fetch()?:[];$s=$pdo->prepare('SELECT id,name FROM services WHERE tenant_id=:t AND active=1 ORDER BY name');$s->execute(['t'=>$t]);$services=$s->fetchAll();$p=$pdo->prepare('SELECT id,name,unit FROM products WHERE tenant_id=:t AND active=1 ORDER BY name');$p->execute(['t'=>$t]);$products=$p->fetchAll();$m=$pdo->prepare('SELECT m.*,s.name service_name,p.name product_name,p.unit FROM auto_service_materials m JOIN services s ON s.id=m.service_id JOIN products p ON p.id=m.product_id WHERE m.tenant_id=:t ORDER BY s.name,p.name');$m->execute(['t'=>$t]);$materials=$m->fetchAll();$st=$pdo->prepare('SELECT st.*,s.name service_name FROM auto_service_steps st JOIN services s ON s.id=st.service_id WHERE st.tenant_id=:t AND st.active=1 ORDER BY s.name,st.sort_order,st.id');$st->execute(['t'=>$t]);View::render('auto/settings',['title'=>'Configurações Automotivas','settings'=>$settings,'services'=>$services,'products'=>$products,'materials'=>$materials,'steps'=>$st->fetchAll()]);
    }

    public function saveSettings():void
    {
        Authorization::require('auto.settings.manage');CSRF::enforce();$t=$this->tenant();$slot=max(5,min(120,(int)($_POST['slot_interval_minutes']??30)));$buffer=max(0,min(240,(int)($_POST['default_buffer_minutes']??10)));$return=max(1,min(730,(int)($_POST['crm_default_return_days']??30)));$terms=trim((string)($_POST['terms_text']??''))?:null;Database::connection()->prepare("INSERT INTO auto_settings(tenant_id,public_enabled,slot_interval_minutes,default_buffer_minutes,require_checkin_photos,require_delivery_acceptance,crm_default_return_days,terms_text,created_at,updated_at)VALUES(:t,:pub,:slot,:buf,:photos,:terms_req,:ret,:terms,NOW(),NOW()) ON DUPLICATE KEY UPDATE public_enabled=VALUES(public_enabled),slot_interval_minutes=VALUES(slot_interval_minutes),default_buffer_minutes=VALUES(default_buffer_minutes),require_checkin_photos=VALUES(require_checkin_photos),require_delivery_acceptance=VALUES(require_delivery_acceptance),crm_default_return_days=VALUES(crm_default_return_days),terms_text=VALUES(terms_text),updated_at=NOW()")
        ->execute(['t'=>$t,'pub'=>isset($_POST['public_enabled'])?1:0,'slot'=>$slot,'buf'=>$buffer,'photos'=>isset($_POST['require_checkin_photos'])?1:0,'terms_req'=>isset($_POST['require_delivery_acceptance'])?1:0,'ret'=>$return,'terms'=>$terms]);header('Location: /auto/settings');exit;
    }

    public function saveMaterial():void
    {
        Authorization::require('auto.settings.manage');CSRF::enforce();$t=$this->tenant();$s=(int)($_POST['service_id']??0);$p=(int)($_POST['product_id']??0);$q=(float)str_replace(',','.',(string)($_POST['quantity']??0));if(!$s||!$p||$q<=0)HttpException::abort(422,'Material inválido.');$pdo=Database::connection();$pdo->prepare('INSERT INTO auto_service_materials(tenant_id,service_id,product_id,quantity)VALUES(:t,:s,:p,:q) ON DUPLICATE KEY UPDATE quantity=VALUES(quantity),tenant_id=VALUES(tenant_id)')->execute(['t'=>$t,'s'=>$s,'p'=>$p,'q'=>$q]);header('Location: /auto/settings');exit;
    }

    public function removeMaterial():void{Authorization::require('auto.settings.manage');CSRF::enforce();$t=$this->tenant();Database::connection()->prepare('DELETE FROM auto_service_materials WHERE tenant_id=:t AND service_id=:s AND product_id=:p')->execute(['t'=>$t,'s'=>(int)($_POST['service_id']??0),'p'=>(int)($_POST['product_id']??0)]);header('Location: /auto/settings');exit;}

    public function saveStep():void
    {
        Authorization::require('auto.settings.manage');CSRF::enforce();$t=$this->tenant();$s=(int)($_POST['service_id']??0);$name=trim((string)($_POST['name']??''));$type=(string)($_POST['step_type']??'service');$minutes=max(0,min(1440,(int)($_POST['expected_minutes']??0)))?:null;if(!$s||mb_strlen($name)<2||!in_array($type,['preparation','service','drying','curing','quality','delivery','other'],true))HttpException::abort(422,'Etapa inválida.');Database::connection()->prepare('INSERT INTO auto_service_steps(tenant_id,service_id,name,step_type,expected_minutes,sort_order,active)VALUES(:t,:s,:n,:type,:m,:o,1)')->execute(['t'=>$t,'s'=>$s,'n'=>$name,'type'=>$type,'m'=>$minutes,'o'=>(int)($_POST['sort_order']??0)]);header('Location: /auto/settings');exit;
    }

    private function tenant():int{$t=TenantContext::id();if(!AutoTenantService::isAutoTenant($t))HttpException::abort(403,'ApPlanner Auto está disponível para Lava-jato, Estética Automotiva e Detailing.');return $t;}
    private function validBay(\PDO $pdo,int $t,int $bay,int $service):bool{$q=$pdo->prepare("SELECT 1 FROM auto_service_bays b WHERE b.id=:b AND b.tenant_id=:t AND b.active=1 AND (NOT EXISTS(SELECT 1 FROM auto_bay_services x WHERE x.bay_id=b.id) OR EXISTS(SELECT 1 FROM auto_bay_services x WHERE x.bay_id=b.id AND x.service_id=:s AND x.tenant_id=:t2))");$q->execute(['b'=>$bay,'t'=>$t,'s'=>$service,'t2'=>$t]);return (bool)$q->fetchColumn();}
    private function jobRow(int $t,int $id):array{$q=Database::connection()->prepare("SELECT j.*,a.customer_id,a.service_id,a.starts_at,a.ends_at,a.professional_id,a.status appointment_status,COALESCE(a.service_price_snapshot,s.price) service_amount,s.name service_name,c.name customer_name,c.phone customer_phone,c.email customer_email,v.make,v.model,v.plate,CONCAT(COALESCE(v.make,''),' ',v.model,IF(v.plate IS NULL OR v.plate='','',CONCAT(' • ',v.plate))) vehicle_label,b.name bay_name,p.name professional_name FROM auto_jobs j JOIN appointments a ON a.id=j.appointment_id JOIN services s ON s.id=a.service_id JOIN customers c ON c.id=a.customer_id JOIN customer_vehicles v ON v.id=j.vehicle_id LEFT JOIN auto_service_bays b ON b.id=j.bay_id LEFT JOIN professionals p ON p.id=j.assigned_professional_id WHERE j.id=:id AND j.tenant_id=:t");$q->execute(['id'=>$id,'t'=>$t]);$r=$q->fetch();if(!$r)HttpException::abort(404,'Ordem não encontrada.');return $r;}
    private function commandRow(\PDO $pdo,int $t,int $id,bool $open=false):array{$q=$pdo->prepare("SELECT ac.*,j.status job_status,a.service_id,c.name customer_name,v.make,v.model,v.plate,CONCAT(COALESCE(v.make,''),' ',v.model,IF(v.plate IS NULL OR v.plate='','',CONCAT(' • ',v.plate))) vehicle_label FROM auto_commands ac JOIN auto_jobs j ON j.id=ac.job_id JOIN appointments a ON a.id=ac.appointment_id JOIN customers c ON c.id=ac.customer_id JOIN customer_vehicles v ON v.id=ac.vehicle_id WHERE ac.id=:id AND ac.tenant_id=:t".($open?" AND ac.status='open'":''));$q->execute(['id'=>$id,'t'=>$t]);$r=$q->fetch();if(!$r)HttpException::abort(404,'Comanda não encontrada.');return $r;}
    private function seedSteps(\PDO $pdo,int $t,int $job,int $service):void{$q=$pdo->prepare('SELECT * FROM auto_service_steps WHERE tenant_id=:t AND service_id=:s AND active=1 ORDER BY sort_order,id');$q->execute(['t'=>$t,'s'=>$service]);foreach($q->fetchAll() as $st)$pdo->prepare('INSERT INTO auto_job_steps(tenant_id,job_id,service_step_id,name,status,sort_order)VALUES(:t,:j,:sid,:n,\'pending\',:o)')->execute(['t'=>$t,'j'=>$job,'sid'=>$st['id'],'n'=>$st['name'],'o'=>$st['sort_order']]);}
    private function history(\PDO $pdo,int $t,int $job,?string $old,string $new,?string $notes=null):void{$pdo->prepare('INSERT INTO auto_job_status_history(tenant_id,job_id,old_status,new_status,user_id,notes,created_at)VALUES(:t,:j,:o,:n,:u,:notes,NOW())')->execute(['t'=>$t,'j'=>$job,'o'=>$old,'n'=>$new,'u'=>Auth::user()['id'],'notes'=>$notes]);}
    private function recalcEstimate(\PDO $pdo,int $t,int $id):void{$q=$pdo->prepare('SELECT COALESCE(SUM(total_amount),0) FROM auto_estimate_items WHERE estimate_id=:e AND tenant_id=:t');$q->execute(['e'=>$id,'t'=>$t]);$sub=(float)$q->fetchColumn();$pdo->prepare('UPDATE auto_estimates SET subtotal=:s,total_amount=GREATEST(0,:s2-discount_amount),updated_at=NOW() WHERE id=:e AND tenant_id=:t')->execute(['s'=>$sub,'s2'=>$sub,'e'=>$id,'t'=>$t]);}
    private function recalcCommand(\PDO $pdo,int $t,int $id):void{$q=$pdo->prepare('SELECT COALESCE(SUM(total_amount),0) FROM auto_command_items WHERE command_id=:c AND tenant_id=:t');$q->execute(['c'=>$id,'t'=>$t]);$sub=(float)$q->fetchColumn();$pdo->prepare('UPDATE auto_commands SET subtotal=:s,total_amount=GREATEST(0,:s2-discount_amount+surcharge_amount),updated_at=NOW() WHERE id=:c AND tenant_id=:t')->execute(['s'=>$sub,'s2'=>$sub,'c'=>$id,'t'=>$t]);}
    private function createAutoCommissions(int $t,int $cmd):void{$pdo=Database::connection();$q=$pdo->prepare("SELECT i.*,p.commission_percent FROM auto_command_items i LEFT JOIN professionals p ON p.id=i.professional_id WHERE i.tenant_id=:t AND i.command_id=:c AND i.professional_id IS NOT NULL AND i.item_type IN('service','product')");$q->execute(['t'=>$t,'c'=>$cmd]);foreach($q->fetchAll() as $i){$rate=(float)($i['commission_percent']??0);if($rate<=0)continue;$amount=round((float)$i['total_amount']*$rate/100,2);$type=$i['item_type']==='service'?'auto_service':'auto_product';$pdo->prepare("INSERT INTO professional_commissions(tenant_id,professional_id,source_type,source_id,gross_amount,rate_percent,commission_amount,status,created_at,updated_at)VALUES(:t,:p,:type,:sid,:gross,:rate,:amount,'pending',NOW(),NOW()) ON DUPLICATE KEY UPDATE gross_amount=VALUES(gross_amount),rate_percent=VALUES(rate_percent),commission_amount=IF(status='pending',VALUES(commission_amount),commission_amount),updated_at=NOW()")->execute(['t'=>$t,'p'=>$i['professional_id'],'type'=>$type,'sid'=>$i['id'],'gross'=>$i['total_amount'],'rate'=>$rate,'amount'=>$amount]);}}
    private function scheduleReturn(int $t,int $jobId):void
    {
        $pdo=Database::connection();$job=$this->jobRow($t,$jobId);$q=$pdo->prepare('SELECT crm_default_return_days FROM auto_settings WHERE tenant_id=:t');$q->execute(['t'=>$t]);$defaultDays=max(1,(int)($q->fetchColumn()?:30));$td=$pdo->prepare('SELECT return_days,warranty_days FROM auto_job_technical_details WHERE tenant_id=:t AND job_id=:j');$td->execute(['t'=>$t,'j'=>$jobId]);$technical=$td->fetch()?:[];$days=isset($technical['return_days'])&&$technical['return_days']!==null?max(1,(int)$technical['return_days']):$defaultDays;$warrantyDays=isset($technical['warranty_days'])&&$technical['warranty_days']!==null?max(0,(int)$technical['warranty_days']):0;$today=new \DateTimeImmutable('today');$next=$today->modify('+'.$days.' days')->format('Y-m-d');$warranty=$warrantyDays>0?$today->modify('+'.$warrantyDays.' days')->format('Y-m-d'):null;
        $pdo->prepare("INSERT INTO auto_vehicle_profiles(vehicle_id,tenant_id,last_service_at,next_recommended_at,warranty_until,updated_at)VALUES(:v,:t,NOW(),:next,:w,NOW()) ON DUPLICATE KEY UPDATE last_service_at=NOW(),next_recommended_at=:next2,warranty_until=COALESCE(:w2,warranty_until),updated_at=NOW()")->execute(['v'=>$job['vehicle_id'],'t'=>$t,'next'=>$next,'w'=>$warranty,'next2'=>$next,'w2'=>$warranty]);
        $pdo->prepare('INSERT INTO auto_vehicle_maintenance(tenant_id,vehicle_id,source_job_id,title,performed_at,next_due_at,warranty_until,created_at)VALUES(:t,:v,:j,:title,CURDATE(),:next,:w,NOW())')->execute(['t'=>$t,'v'=>$job['vehicle_id'],'j'=>$jobId,'title'=>$job['service_name'],'next'=>$next,'w'=>$warranty]);
        $pdo->prepare("INSERT IGNORE INTO auto_crm_events(tenant_id,vehicle_id,customer_id,event_type,due_at,status,created_at,updated_at)VALUES(:t,:v,:c,'return_due',:d,'pending',NOW(),NOW())")->execute(['t'=>$t,'v'=>$job['vehicle_id'],'c'=>$job['customer_id'],'d'=>$next]);
    }

    private function ensureDeliveryTerm(int $t,int $jobId):void{$pdo=Database::connection();$q=$pdo->prepare('SELECT require_delivery_acceptance,terms_text FROM auto_settings WHERE tenant_id=:t');$q->execute(['t'=>$t]);$s=$q->fetch();if(!$s||empty($s['require_delivery_acceptance'])||trim((string)$s['terms_text'])==='')return;$e=$pdo->prepare('SELECT 1 FROM auto_delivery_terms WHERE tenant_id=:t AND job_id=:j');$e->execute(['t'=>$t,'j'=>$jobId]);if($e->fetchColumn())return;$token=bin2hex(random_bytes(24));$pdo->prepare('INSERT INTO auto_delivery_terms(tenant_id,job_id,public_token_hash,public_token_encrypted,terms_snapshot,created_at)VALUES(:t,:j,:h,:e,:terms,NOW())')->execute(['t'=>$t,'j'=>$jobId,'h'=>hash('sha256',$token),'e'=>\App\Core\Encryption::encrypt(['token'=>$token]),'terms'=>$s['terms_text']]);}
    private function money(mixed $v):?float{$s=str_replace(['R$',' ','\.'],['','',''],trim((string)$v));$s=str_replace(',','.',$s);return is_numeric($s)?round((float)$s,2):null;}
}
